"""Read-only workload progress; update only this worktree's status document."""
import json
from pathlib import Path
from datetime import datetime, timezone
root=Path.cwd()
p=next((root/'artifacts/exp39-20261014-r2').glob('windows-*'))
results=json.loads((p/'results.json').read_text()) if (p/'results.json').exists() else []
if (p/'continuation.json').exists():
 results=[r for r in results if not (r['repeat']==3 and r['policy']=='2')]
queue=p/'queue-age.jsonl'
row=json.loads(queue.read_text().splitlines()[-1]) if queue.exists() else {}
counts={state:sum(j['state']==state for j in row.get('jobs',[])) for state in ['queued','processing','succeeded','failed']}
message={'utc':datetime.now(timezone.utc).isoformat(),'phase':row.get('phase'),'completed_windows':len(results),'planned_windows':48,'current_jobs':counts,'oldest_seconds':round(row.get('oldest_seconds',0),1)}
status=root/'docs/execution/experiments-20261014/STATUS.txt'
body=status.read_text().split('LIVE PROGRESS:')[0]
status.write_text(body+'LIVE PROGRESS: '+json.dumps(message,separators=(',',':'))+'\n')
for name in (['continuation-failure.json','completion.json'] if (p/'continuation.json').exists() else ['failure.json','completion.json']):
 if (p/name).exists():message[name]=json.loads((p/name).read_text())
print(json.dumps(message))

import json
from pathlib import Path
root=Path.cwd();run='exp39-20261014-r2';p=root/'artifacts'/run
result=next(p.glob('experimental-baseline-recovery-*/result.json'),None)
summary={}
if result:
 r=json.loads(result.read_text());summary={'recovery_status':r['status'],'cases':{k:v['status'] for k,v in r.get('cases',{}).items()}}
 names=['worker-kill','queue-loss-repair','durable-backlog-namespace-restart','redis-db-loss-repair','60s-decoded-cost-input','restoration-http-ready']
 events=[e for e in r.get('events',[]) if e['event'] in names]
 summary['proof_counts']={name:sum(e['event']==name for e in events) for name in names}
 summary['latest_proof']={k:v for k,v in events[-1].items() if k in ['event','at','reenqueue_seconds','visible_failure_seconds','elapsed_seconds','jobs','bound_seconds']} if events else None
j=root/'.local/runs'/run/'releases/journal.json'
if j.exists():
 r=json.loads(j.read_text());summary['release_operations']=[{'action':x['action'],'status':x['status']} for x in r.get('operations',[])]
for directory in p.glob('faults-baseline-*'):
 if not directory.is_dir():continue
 for name in ['active-long-drain.json','active-rollback.json','release-result.json']:
  f=directory/name
  if f.exists():
   v=json.loads(f.read_text());summary[name]={k:v.get(k) for k in ['processing_seconds','drain_seconds','status','exit'] if k in v}
status=root/'docs/execution/experiments-20261014/STATUS.txt'
body=status.read_text().split('LIVE PROGRESS:')[0];status.write_text(body+'LIVE PROGRESS: '+json.dumps(summary,separators=(',',':'))+'\n')
print(json.dumps(summary))
